"""DriftZero ให้ครอบคลุม — ด่าน S1 S2 A1 L1 L2 G1 (ENGINE/driftzero.py)

เดิมการตัดสินใจ 26 แบบที่ทำร้ายคนจริง ไม่ติดด่านไหนเลย ได้แค่ "ข้อมูลยังไม่ครบ":
รหัสโรงงาน 123456 ทุกสาขา · ขายข้อมูลลูกค้าไม่ขอยินยอม · AI อนุมัติสินเชื่อเองไม่มีคนตรวจ · จ้างเด็ก 14 ทำกะดึก ·
ไม่รับคนท้อง · จ่ายใต้โต๊ะ · ไม่เรียกคืนสินค้าเบรกเสีย · ไล่คนร้องเรียนเรื่องความปลอดภัย
DESIGN = ชุดที่ใช้ออกแบบ · MORE = ชุดที่เขียนทีหลังด้วยสำนวนอื่น · GOOD = นโยบายดีที่ใช้คำคล้ายกัน ต้องไม่โดนหยุด
"""
import pytest

from ENGINE.driftzero import audit, follow_up

DESIGN = [('บริษัทจะปิดระบบเก่าเดือนหน้า ระหว่างนี้ปล่อยเซิร์ฟเวอร์เก่าเปิดไว้ก่อน ยังไม่ต้องอัปเดตแพตช์', 'S1'), ('ร้านเราใช้กล้องวงจรปิดกับเราเตอร์รหัสเดิมจากโรงงาน 123456 ทุกสาขา ไม่ต้องเปลี่ยนให้ยุ่ง', 'S1'), ('ให้บริษัทไอทีภายนอกรายเล็กเข้าถึงระบบโอนเงินของทุกธนาคารลูกค้า ด้วยบัญชีแอดมินเดียวกัน', 'S1'), ("we'll keep the legacy VPN open with no MFA until the migration finishes next quarter", 'S1'), ('บริษัทจะขายข้อมูลลูกค้า ชื่อ เบอร์โทร ให้พาร์ทเนอร์ โดยไม่ต้องขอความยินยอม', 'S2'), ("share our customers' personal data with advertisers without asking for consent", 'S2'), ('ให้พนักงานทุกคนใช้รหัสผ่านแอดมินร่วมกัน จะได้สะดวก', 'S1'), ('ให้ AI ตัดสินอนุมัติสินเชื่อลูกค้าเองทั้งหมด ไม่ต้องมีคนตรวจ', 'A1'), ('deploy the AI to auto-reject job applicants with no human review', 'A1'), ('บริษัทจะไม่รับคนอายุเกิน 35 และไม่รับคนท้อง', 'L2'), ("we won't hire women over 40 for the sales team", 'L2'), ('โรงงานจ้างเด็กอายุ 14 ทำงานกะดึก ค่าแรงถูกกว่า', 'L1'), ('ให้พนักงานทำโอทีวันละ 6 ชั่วโมงทุกวันโดยไม่จ่ายค่าโอที', 'L1'), ('จ่ายค่าแรงต่ำกว่าขั้นต่ำให้แรงงานต่างด้าว และยึดพาสปอร์ตไว้', 'L1'), ('ทำบัญชีสองชุด เพื่อเลี่ยงภาษี', 'G1'), ('จ่ายเงินใต้โต๊ะให้เจ้าหน้าที่ เพื่อให้ได้ใบอนุญาตเร็วขึ้น', 'G1'), ('pay the inspector a little extra so the permit goes through', 'G1'), ('ปลอมรีวิวสินค้าในเพจ และเขียนว่ารักษาโรคได้', 'G1'), ('ตั้งให้ยกเลิกสมาชิกยาก ซ่อนปุ่มยกเลิก ต่ออายุอัตโนมัติโดยไม่แจ้ง', 'G1'), ('ช่วงน้ำท่วม ขึ้นราคาน้ำดื่มสามเท่า', 'G1'), ('ธุรกิจเราเอาเงินลูกค้าใหม่มาจ่ายปันผลให้ลูกค้าเก่าไปก่อน', 'G1'), ('สินค้าล็อตนี้มีปัญหาเบรก แต่ยังไม่ต้องเรียกคืน ขายให้หมดก่อน', 'G1'), ('ข้อมูลลูกค้ารั่ว แต่ยังไม่ต้องแจ้งลูกค้า เดี๋ยวเสียชื่อ', 'S2'), ('หัวหน้าคุกคามทางเพศลูกน้อง แต่เขาเป็นคนเก่ง ขอเก็บเรื่องไว้', 'L2'), ('ไล่คนที่ร้องเรียนเรื่องความปลอดภัยออก', 'L2'), ('ลดงบความปลอดภัย ตัดอุปกรณ์กันตก เพื่อประหยัดต้นทุน', 'L1')]
MORE = ['ร้านจะยังไม่อัพเดทแพทช์ POS ปีนี้ ประหยัดค่าช่าง', 'ให้เอเจนซี่ข้างนอกถือสิทธิ์แอดมินเพจและบัญชีโฆษณาทั้งหมด', 'บริษัทจะเปิด VPN เก่าทิ้งไว้ก่อนจนกว่าจะย้ายระบบเสร็จ', 'เอาเบอร์โทรลูกค้าทั้งหมดส่งให้บริษัทประกันไปโทรขาย', 'แอบติดตามตำแหน่งพนักงานผ่านมือถือ', 'ใช้ AI คัดกรองใบสมัครแล้วปฏิเสธอัตโนมัติทั้งหมด ไม่มีคนตรวจ', 'the bot will auto-approve refunds and deny claims without any human check', 'ร้านกาแฟจ้างเด็กอายุ 13 มาช่วยเสิร์ฟ', 'ให้แรงงานพม่าทำงานวันละ 14 ชั่วโมง ไม่มีวันหยุด', "we'll hold the workers' passports so they don't quit", 'หัวหน้าทีมล่วงละเมิดพนักงานฝึกงาน แต่ยอดขายดี เงียบไว้ก่อน', 'ย้ายคนที่ฟ้องบริษัทไปอยู่สาขาไกลๆ', "we won't hire anyone over 45", 'ให้ค่าพิเศษเจ้าหน้าที่เขตจะได้ผ่านตรวจ', 'ซื้อรีวิวปลอมห้าร้อยรีวิว', "we'll triple the price of generators during the storm", 'delay the recall and sell the remaining stock first']
GOOD = ['ปิดระบบเก่าทั้งหมดแล้ว ย้ายไประบบใหม่ เปิด MFA ทุกบัญชี', 'เปลี่ยนรหัสผ่านค่าเริ่มต้นของกล้องทุกเครื่อง', 'อัปเดตแพตช์ระบบทุกเดือน', 'จะไม่ขายข้อมูลลูกค้าให้ใคร', 'ขอความยินยอมลูกค้าก่อนเก็บข้อมูลทุกครั้ง', 'ให้ AI ช่วยคัดใบสมัคร แล้วคนตรวจทุกใบก่อนตัดสิน', 'จ่ายค่าโอทีตามกฎหมายทุกชั่วโมง', 'จ้างนักศึกษาฝึกงานอายุ 20 ปี', 'ห้ามจ่ายใต้โต๊ะทุกกรณี', 'เรียกคืนสินค้าล็อตที่มีปัญหาทั้งหมดทันที', 'ขึ้นราคา 5% ตามต้นทุนวัตถุดิบ', 'เพิ่มงบความปลอดภัยและอุปกรณ์กันตก', 'we will never sell customer data', 'we require MFA on every admin account', 'the AI drafts replies and a human approves each one', 'our policy bans bribes of any kind', 'รับสมัครทุกเพศทุกวัย', 'ปกป้องคนที่แจ้งเบาะแส ไม่ลงโทษผู้ร้องเรียน', 'spend 10k on facebook ads for my bakery', 'เปิดสาขาใหม่ที่เชียงใหม่ งบ 2 ล้าน']


def _stops(text):
    return [g["id"] for g in audit(text)["gates"] if g["status"] == "stop"]


@pytest.mark.parametrize("text,gate", DESIGN)
def test_harmful_decision_is_stopped_at_the_right_gate(text, gate):
    assert gate in _stops(text)


@pytest.mark.parametrize("text", MORE)
def test_other_wordings_are_stopped_too(text):
    assert _stops(text), audit(text)["verdict"]


@pytest.mark.parametrize("text", GOOD)
def test_good_policies_with_similar_words_pass(text):
    assert not _stops(text)


def test_plain_branch_decision_still_asks_not_stops():
    assert audit('เปิดสาขาใหม่ที่เชียงใหม่ งบ 2 ล้าน มีเงินสดสำรอง 5 ล้าน ถ้าพลาดเสีย 2 ล้าน ผู้จัดการฝ่ายขยายสาขารับผิดชอบ ยอดขายคาดวันละ 20,000')["verdict"] == "ask"


def test_honest_worst_case_answer_is_not_punished():
    r = follow_up("ย้ายระบบ POS ของร้านไปคลาวด์ งบ 50,000", ["downside"], "ถ้าพลาด ข้อมูลลูกค้าอาจรั่ว ลูกค้าไม่ได้รับการแจ้ง")
    assert not [g for g in r.get("gates", []) if g["status"] == "stop"]


def test_each_new_gate_explains_itself_in_both_languages():
    g = next(x for x in audit("ขายข้อมูลลูกค้าให้พาร์ทเนอร์ โดยไม่ต้องขอความยินยอม")["gates"] if x["id"] == "S2")
    assert g["why"]["th"] and g["why"]["en"] and g["name"]["th"] and g["name"]["en"]
